// ---------------------------------------------------------------- API
async function api(url, body) {
  const res = await fetch(url, body ? { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) } : undefined);
  const j = await res.json();
  if (!res.ok) throw Object.assign(new Error(j.message || res.statusText), { code: j.error });
  return j;
}
async function grid(url, f32 = false) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  const buf = await res.arrayBuffer();
  return { w: +res.headers.get('x-width'), h: +res.headers.get('x-height'), data: f32 ? new Float32Array(buf) : new Uint8Array(buf) };
}

